export const defaultAppearance={hue:267,bg:'#08090b',paper:'#101114',raised:'#1b1c20',field:'#0b0c0f',ink:'#e8e8eb',muted:'#a2a3aa',line:'#2b2d33',accent:'#c6c8ce',accentInk:'#0b0c0f',artColor:'#4d5059',autoContrast:true,art:14,grain:8,motion:true,smooth:true};
export const paletteFields=[['bg','Фон страницы'],['paper','Фон панелей'],['raised','Кнопки и выделение'],['field','Фон полей'],['ink','Основной текст'],['muted','Вторичный текст'],['line','Границы'],['accent','Акцент'],['accentInk','Текст на акценте'],['artColor','Фоновая графика']];
const previousPalette={bg:'#0b0911',paper:'#191320',raised:'#292031',field:'#110c19',ink:'#faf7ff',muted:'#c8bdd7',line:'#59456e',accent:'#b98aff',accentInk:'#160d22',artColor:'#a574e5'};
function upgradeDefault(value){const old=value.autoContrast!==false&&Number(value.hue??267)===267&&paletteFields.every(([key])=>value[key]===undefined||String(value[key]).toLowerCase()===previousPalette[key]||(key==='accent'&&String(value[key]).toLowerCase()==='#ae96f0'));if(!old)return value;return {...value,...Object.fromEntries(paletteFields.map(([key])=>[key,defaultAppearance[key]])),art:value.art===undefined||Number(value.art)===32?defaultAppearance.art:value.art,grain:value.grain===undefined||Number(value.grain)===12?defaultAppearance.grain:value.grain};}
const clamp=(v,min,max)=>Math.max(min,Math.min(max,Number(v)||min));
const hex=(value,fallback)=>/^#[\da-f]{6}$/i.test(value||'')?value.toLowerCase():fallback;
export function luminance(hex){const channels=hex.replace('#','').match(/../g).map(c=>parseInt(c,16)/255).map(c=>c<=.04045?c/12.92:((c+.055)/1.055)**2.4);return channels[0]*.2126+channels[1]*.7152+channels[2]*.0722;}
export function contrast(a,b){const x=luminance(a),y=luminance(b);return(Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
function readable(value,surfaces,minimum=4.5){if(surfaces.every(bg=>contrast(value,bg)>=minimum))return value;const rgb=value.slice(1).match(/../g).map(c=>parseInt(c,16));let best=value,score=0;for(let n=0;n<=100;n++)for(const end of [255,0]){const candidate='#'+rgb.map(c=>Math.round(c+(end-c)*n/100).toString(16).padStart(2,'0')).join(''),ratio=Math.min(...surfaces.map(bg=>contrast(candidate,bg)));if(ratio>=minimum)return candidate;if(ratio>score){best=candidate;score=ratio;}}return best;}
export function safeAccent(value){return readable(hex(value,defaultAppearance.accent),['#201a2d']);}
function legacyTone(hue,saturation,lightness){const c=(1-Math.abs(2*lightness-1))*saturation,x=c*(1-Math.abs((hue/60)%2-1)),m=lightness-c/2,colors=[[c,x,0],[x,c,0],[0,c,x],[0,x,c],[x,0,c],[c,0,x]][Math.min(5,Math.floor(hue/60))];return '#'+colors.map(v=>Math.round((v+m)*255).toString(16).padStart(2,'0')).join('');}
export function normalizeAppearance(value={}){value=upgradeDefault(value||{});const hue=clamp(value.hue??267,0,360),settings={hue,autoContrast:value.autoContrast!==false,art:clamp(value.art??defaultAppearance.art,0,100),grain:clamp(value.grain??defaultAppearance.grain,0,40),motion:value.motion!==false,smooth:value.smooth!==false};for(const[key]of paletteFields)settings[key]=hex(value[key],defaultAppearance[key]);if(hue!==267){for(const[key,s,l]of [['bg',.3,.05],['paper',.25,.1],['raised',.22,.16],['field',.3,.065],['line',.23,.35]])if(!value[key])settings[key]=legacyTone(hue,s,l);}
  if(settings.autoContrast){const surfaces=[settings.bg,settings.paper,settings.raised,settings.field];settings.ink=readable(settings.ink,surfaces);settings.muted=readable(settings.muted,surfaces);settings.accent=readable(settings.accent,surfaces);settings.accentInk=readable(settings.accentInk,[settings.accent]);}return settings;}
export function appearanceContrast(settings){return Math.min(...[settings.bg,settings.paper,settings.raised,settings.field].flatMap(bg=>[contrast(settings.ink,bg),contrast(settings.muted,bg)]),contrast(settings.accentInk,settings.accent));}
export function applyAppearance(value){const settings=normalizeAppearance(value),style=document.documentElement.style;style.setProperty('--theme-hue',settings.hue);for(const[key]of paletteFields)style.setProperty(key==='accentInk'?'--accent-ink':'--'+key,settings[key]);style.setProperty('--sidebar',settings.paper);style.setProperty('--accent-bg','color-mix(in srgb,var(--accent) 18%,var(--paper))');style.setProperty('--art-opacity',settings.art/100);style.setProperty('--grain-opacity',settings.grain/100);document.documentElement.dataset.motion=String(settings.motion);document.documentElement.dataset.smooth=String(settings.smooth);return settings;}
export function readAppearanceForm(form){const value={};for(const[key]of paletteFields)value[key]=form.querySelector('#appearance-'+key).value;for(const key of ['autoContrast','motion','smooth'])value[key]=form.querySelector('#appearance-'+key).checked;for(const key of ['art','grain'])value[key]=form.querySelector('#appearance-'+key).value;return value;}
export function wireAppearanceForm(form){const status=form.querySelector('#appearance-contrast'),preview=()=>{const settings=applyAppearance(readAppearanceForm(form)),ratio=appearanceContrast(settings);status.textContent='Контраст текста: '+ratio.toFixed(1)+':1'+(ratio<4.5?' · Низкий контраст — измените цвета или включите автоконтраст.':' · Хорошая читаемость');status.classList.toggle('contrast-warning',ratio<4.5);};form.addEventListener('input',event=>{const target=event.target,key=target.dataset.color||target.dataset.hex;if(key){const picker=form.querySelector('#appearance-'+key),text=form.querySelector('[data-hex="'+key+'"]');if(target.dataset.hex){const valid=/^#[\da-f]{6}$/i.test(target.value);target.setCustomValidity(valid?'':'Цвет в формате #RRGGBB');if(!valid)return;picker.value=target.value;}else{text.value=picker.value;text.setCustomValidity('');}}preview();});preview();}
export function appearanceForm(value){const s=normalizeAppearance(value);return `<section class="panel appearance-panel"><h2>Цвет и движение</h2><p>Каждый цвет можно задать отдельно. Предпросмотр работает сразу; изменения сохраняются по кнопке.</p><form id="appearance-form"><div class="appearance-color-grid">${paletteFields.map(([key,label])=>`<div class="field"><label for="appearance-${key}">${label}</label><div class="appearance-color-pair"><input id="appearance-${key}" data-color="${key}" type="color" value="${s[key]}"><input data-hex="${key}" aria-label="HEX: ${label}" value="${s[key]}" maxlength="7" pattern="#[a-fA-F0-9]{6}" required spellcheck="false"></div></div>`).join('')}</div><label class="layout-checkbox"><input id="appearance-autoContrast" type="checkbox" ${s.autoContrast?'checked':''}>Автоконтраст — помогает сохранить читаемость. Отключите для точного управления цветами.</label><p id="appearance-contrast" role="status"></p><div class="appearance-effects"><div class="field"><label for="appearance-art">Яркость фоновой графики</label><input id="appearance-art" type="range" min="0" max="100" value="${s.art}"></div><div class="field"><label for="appearance-grain">Зерно</label><input id="appearance-grain" type="range" min="0" max="40" value="${s.grain}"></div></div><label class="layout-checkbox"><input id="appearance-motion" type="checkbox" ${s.motion?'checked':''}>Анимация фона</label><label class="layout-checkbox"><input id="appearance-smooth" type="checkbox" ${s.smooth?'checked':''}>Плавная прокрутка с инерцией</label><div class="modal-footer"><button type="button" class="btn" id="appearance-reset">Сбросить тему</button><button type="submit" class="btn btn-primary">Сохранить</button></div></form></section>`;}

export function installSmoothScroll(){
  let target=null,current=0,frame=0,last=0,scroller=null,writing=false;
  const root=()=>document.scrollingElement;
  function cancel(){if(frame)cancelAnimationFrame(frame);frame=0;target=null;scroller=null;}
  function tick(now){if(!scroller||target===null)return;const dt=Math.min(32,now-last||16);last=now;current+=(target-current)*(1-Math.exp(-dt/85));writing=true;scroller.scrollTop=current;writing=false;if(Math.abs(target-current)<.45){scroller.scrollTop=target;cancel();}else frame=requestAnimationFrame(tick);}
  document.addEventListener('wheel',event=>{
    if(event.ctrlKey||event.metaKey||Math.abs(event.deltaX)>Math.abs(event.deltaY)||document.documentElement.dataset.smooth==='false'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
    if(event.target.closest('.office-viewport,input,textarea,[contenteditable],.custom-select-popover'))return;
    // Preserve native touchpad inertia: smooth only discrete mouse-wheel steps.
    if(event.deltaMode===0&&Math.abs(event.deltaY)<36)return;
    let el=event.target.closest?.('.modal,.office-detail,.office-seat-list,.sidebar');if(!el||el.scrollHeight<=el.clientHeight)el=root();
    if(document.body.classList.contains('scroll-locked')&&el===root())return;
    const delta=event.deltaY*(event.deltaMode===1?28:event.deltaMode===2?el.clientHeight:1),max=Math.max(0,el.scrollHeight-el.clientHeight);
    const base=el===scroller&&target!==null?target:el.scrollTop,next=Math.max(0,Math.min(max,base+delta));if(next===base)return;event.preventDefault();
    if(scroller!==el){cancel();scroller=el;current=el.scrollTop;}target=next;if(!frame){last=performance.now();frame=requestAnimationFrame(tick);}
  },{passive:false});
  document.addEventListener('pointerdown',cancel,true);document.addEventListener('touchstart',cancel,{passive:true});document.addEventListener('keydown',event=>{if(['Escape','Home','End','PageUp','PageDown','ArrowUp','ArrowDown',' '].includes(event.key))cancel();});window.addEventListener('hashchange',cancel);
  document.addEventListener('scroll',event=>{const el=event.target===document?root():event.target;if(scroller===el&&!writing&&Math.abs(el.scrollTop-current)>3)cancel();},true);
}
